struct customer { long id; char name[64]; UT_hash_handle hh; };
struct session  { struct customer *by_id; };   /* initialise to NULL */

struct customer *session_get(struct session *s, long id) {
    struct customer *c;
    HASH_FIND(hh, s->by_id, &id, sizeof id, c);
    if (!c) { c = load_customer(id); HASH_ADD(hh, s->by_id, id, sizeof id, c); }
    return c;                                  /* one pointer per row */
}
